import sys
from collections import deque

def main():
    n, d = map(int, sys.stdin.readline().split())
    coords = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]
    d_squared = d * d
    adj = [[] for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i != j:
                dx = coords[i][0] - coords[j][0]
                dy = coords[i][1] - coords[j][1]
                dist_sq = dx * dx + dy * dy
                if dist_sq <= d_squared:
                    adj[i].append(j)

    visited = [False] * n
    q = deque()
    q.append(0)
    visited[0] = True

    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)

    for i in range(n):
        print("Yes" if visited[i] else "No")

if __name__ == "__main__":
