    idx = 1
    for _ in range(Q):
        t = input[idx]
        if t == '1' or t == '2':
            x = int(input[idx + 1])
            if t == '1':
                counts[x] += 1
            else:
                counts[x] -= 1
                if counts[x] == 0:
                    del counts[x]
            idx += 2
        else:
            print(len(counts))
            idx += 1

